const labels={pop_est:'Population',admin_nm:'District'};
const dl=document.createElement('dl');
for(const [k,t] of Object.entries(labels)){
  const dt=document.createElement('dt'), dd=document.createElement('dd');
  dt.textContent=t; dd.textContent=p[k]; dl.append(dt,dd);
}

const el=document.createElement('div');
const h=document.createElement('h3'); h.textContent=p.name;
const d=document.createElement('p'); d.textContent='Population: '+p.pop.toLocaleString();
el.append(h,d); popup.setDOMContent(el);

